import itertools
import unittest

from duration import parse_duration


class ParseDurationTests(unittest.TestCase):
    def test_single_units(self):
        for text, expected in (("0s", 0), ("3s", 3), ("2m", 120), ("4h", 14400)):
            with self.subTest(text=text):
                self.assertEqual(parse_duration(text), expected)

    def test_adjacent_pairs_and_all_orders(self):
        self.assertEqual(parse_duration("1h30m"), 5400)
        for pairs in itertools.permutations(("1h", "2m", "3s")):
            with self.subTest(pairs=pairs):
                self.assertEqual(parse_duration("".join(pairs)), 3723)

    def test_whitespace(self):
        self.assertEqual(parse_duration(" \t1h\n30m  5s\r "), 5405)

    def test_zero_leading_zero_and_large_values(self):
        self.assertEqual(parse_duration("0h0m0s"), 0)
        self.assertEqual(parse_duration("001h002m003s"), 3723)
        self.assertEqual(parse_duration("1000000000000000h"), 3600000000000000000)
        self.assertEqual(parse_duration("90m90s"), 5490)

    def test_empty_and_unknown_units(self):
        for text in ("", " \t\n", "1d", "1H", "1M", "1S", "3", "h", "1hour"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_duration(text)

    def test_signs_decimals_and_non_ascii_digits(self):
        for text in ("-1s", "+1h", "1.5m", "1h-2m", "1h+2m", "١s", "１s"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_duration(text)

    def test_repeated_units(self):
        for text in ("1h2h", "1m 0m", "1s2s", "1h2m3h", "0s0s"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_duration(text)

    def test_junk_and_whitespace_within_pairs(self):
        for text in ("1s!", "junk1s", "1h 2m trailing", "1s2", "1h,2m", "1 s", "1\tm"):
            with self.subTest(text=text):
                with self.assertRaises(ValueError):
                    parse_duration(text)


if __name__ == "__main__":
    unittest.main()
